from typing import TypeVar, Generic, Union

T = TypeVar('T')

class Some(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def __repr__(self) -> str:
        return f"Some({self.value!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Some):
            return NotImplemented
        return self.value == other.value

class _NoneType:
    def __repr__(self) -> str:
        return "None"

    def __eq__(self, other: object) -> bool:
        return isinstance(other, _NoneType)

NONE = _NoneType()

Option = Union[Some[T], _NoneType]

def safe_divide(numerator: float, divisor: float) -> Option[float]:
    if divisor == 0.0:
        return NONE
    else:
        return Some(numerator / divisor)

def print_option_result(option: Option[float]) -> None:
    if isinstance(option, Some):
        print(f"Result: {option.value}")
    elif isinstance(option, _NoneType):
        print("Error: Division by zero")

if __name__ == "__main__":
    result1 = safe_divide(10.0, 2.0)
    result2 = safe_divide(10.0, 0.0)

    print_option_result(result1)
    print_option_result(result2)

