from typing import TypeVar, Generic, Union

T = TypeVar('T')

class Ok(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def __repr__(self) -> str:
        return f"Ok({self.value!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Ok):
            return NotImplemented
        return self.value == other.value

class Err:
    def __init__(self, message: str):
        self.message = message

    def __repr__(self) -> str:
        return f"Err({self.message!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Err):
            return NotImplemented
        return self.message == other.message

Result = Union[Ok[T], Err]

def parse_int(s: str) -> Result[int]:
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def run_test_case(input_str: str, divisor: int):
    parsed_result = parse_int(input_str)

    if isinstance(parsed_result, Ok):
        division_result = divide_safe(parsed_result.value, divisor)
        if isinstance(division_result, Ok):
            print(f"Result: {division_result.value}")
        else:
            print(f"Error: {division_result.message}")
    else:
        print(f"Error: {parsed_result.message}")

run_test_case("10", 2)
