export func filter[a](pred: func(a) -> bool, xs: List[a]) -> List[a] {
  match xs {
    [] => [],
    Cons(x, rest) =>
      if pred(x)
      then Cons(x, filter(pred, rest))
      else filter(pred, rest)
  }
}

export func map[a, b](f: func(a) -> b, xs: List[a]) -> List[b] {
  match xs {
    [] => [],
    Cons(x, rest) => Cons(f(x), map(f, rest))
  }
}

export func foldl[a, b](f: func(b, a) -> b, acc: b, xs: List[a]) -> b {
  match xs {
    [] => acc,
    Cons(x, rest) => foldl(f, f(acc, x), rest)
  }
}

