type Tree = Leaf(int) | Node(Tree, int, Tree)

export func tree_sum(tree: Tree) -> int {
  match tree {
    Leaf(v) => v,
    Node(l, v, r) => tree_sum(l) + v + tree_sum(r)
  }
}

export func find_max(tree: Tree) -> int {
  match tree {
    Leaf(v) => v,
    Node(l, v, r) => {
      let left_max = find_max(l);
      let right_max = find_max(r);
      if v >= left_max && v >= right_max
      then v
      else if left_max >= right_max
      then left_max
      else right_max
    }
  }
}

export func main() -> () ! {IO} {
  let tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)));
  let sum = tree_sum(tree);
  let max = find_max(tree);
  print("Sum: " ++ show(sum) ++ "\n");
  print("Max: " ++ show(max))
